mapper.select:
SELECT 
FROM crm_annual_report
WHERE tenant_id = #{tenantId} AND id = #{id}

SELECT r.id AS id, r.customer_id AS customerId, r.owner_staff_id AS ownerStaffId, r.team_id AS teamId, r.report_year AS reportYear, r.share_key AS shareKey, r.tone_code AS toneCode, r.tone_reason AS toneReason, r.display_name_snapshot AS displayNameSnapshot, r.tier_label_snapshot AS tierLabelSnapshot, r.butler_name_snapshot AS butlerNameSnapshot, r.order_count AS orderCount, r.net_spend_fen AS netSpendFen, r.redeem_count AS redeemCount, r.remaining_entitlement_count AS remainingEntitlementCount, r.status AS status, r.created_at AS createdAt, r.version AS version, COALESCE(v.visit_count, 0) AS visitCount, COALESCE(v.total_visible_duration_ms, 0) AS totalVisibleDurationMs, COALESCE(v.max_scene_reached, 0) AS maxSceneReached, COALESCE(v.max_viewed_scene_count, 0) AS maxViewedSceneCount, COALESCE(v.generated_poster, 0) = 1 AS generatedPoster, COALESCE(v.clicked_book_butler, 0) = 1 AS clickedBookButler, v.last_active_at AS lastActiveAt FROM crm_annual_report r JOIN crm_customer c ON c.tenant_id = r.tenant_id AND c.id = r.customer_id AND c.deleted = 0 LEFT JOIN ( SELECT report_id, COUNT(*) AS visit_count, COALESCE(SUM(visible_duration_ms), 0) AS total_visible_duration_ms, COALESCE(MAX(max_scene_reached), 0) AS max_scene_reached, COALESCE(MAX(viewed_scene_count), 0) AS max_viewed_scene_count, MAX(generated_poster) AS generated_poster, MAX(clicked_book_butler) AS clicked_book_butler, MAX(last_active_at) AS last_active_at FROM crm_annual_report_visit_session WHERE tenant_id = #{tenantId} GROUP BY report_id ) v ON v.report_id = r.id WHERE r.tenant_id = #{tenantId}
AND r.report_year = #{reportYear}
AND r.customer_id = #{customerId}
AND r.status = #{status}
ORDER BY r.created_at DESC, r.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM crm_annual_report r
JOIN crm_customer c ON c.tenant_id = r.tenant_id AND c.id = r.customer_id AND c.deleted = 0
WHERE r.tenant_id = #{tenantId}


  AND r.report_year = #{reportYear}


  AND r.customer_id = #{customerId}


  AND r.status = #{status}

SELECT 
FROM crm_annual_report_visit_session
WHERE tenant_id = #{tenantId}
  AND report_id = #{reportId}
  AND session_key = #{sessionKey}
FOR UPDATE

SELECT 
FROM crm_annual_report_visit_session
WHERE tenant_id = #{tenantId}
  AND report_id = #{reportId}
ORDER BY last_active_at DESC, id DESC
LIMIT #{limit}

