SELECT order_id AS orderId, sku_name_snapshot AS skuNameSnapshot, purchase_quantity AS purchaseQuantity FROM crm_order_item WHERE tenant_id = #{tenantId} AND order_id IN
#{oid}
ORDER BY id ASC

SELECT e.id AS entitlementId, oi.order_id AS orderId, e.project_id AS projectId, p.project_name AS projectName, p.category_code AS categoryCode, e.granted_count AS grantedCount, e.available_count AS availableCount, e.valid_to AS validTo, e.status AS status FROM crm_entitlement e JOIN crm_order_item oi ON oi.tenant_id = e.tenant_id AND oi.id = e.order_item_id JOIN crm_project p ON p.tenant_id = e.tenant_id AND p.id = e.project_id WHERE e.tenant_id = #{tenantId} AND e.customer_id = #{customerId} AND oi.order_id IN
#{oid}
ORDER BY e.id ASC

SELECT
  id,
  COALESCE(contact_at, created_at) AS contactAt
FROM crm_followup
WHERE tenant_id = #{tenantId}
  AND customer_id = #{customerId}
  AND deleted = 0
  AND COALESCE(contact_at, created_at) >= #{startInclusive}
  AND COALESCE(contact_at, created_at) < #{endExclusive}
ORDER BY COALESCE(contact_at, created_at) ASC, id ASC

SELECT tag_code
FROM crm_customer_tag
WHERE tenant_id = #{tenantId}
  AND customer_id = #{customerId}
ORDER BY id ASC

SELECT display_name
FROM sys_user
WHERE tenant_id = #{tenantId}
  AND id = #{userId}

SELECT MIN(COALESCE(paid_at, ordered_at, created_at))
FROM crm_order
WHERE tenant_id = #{tenantId}
  AND customer_id = #{customerId}
  AND status NOT IN ('DRAFT', 'CANCELED')
  AND paid_fen > 0
